// distKm(type, maxKm, minW): Float32Array(w*h), km to the nearest point of that type (minus its radius), Infinity beyond maxKm.
// kernel(type, lambdaKm, maxKm): Float32Array(w*h), max over points of weight * exp(-d / lambdaKm), 0 beyond maxKm.
window.PSAREMA_ATTRACTORS._grid = function (type, maxKm, f, init, minW) {
  const W = this.w, H = this.h, R = this.res, KX = R * 111.32 * Math.cos(35 * Math.PI / 180), KY = R * 110.57, out = new Float32Array(W * H).fill(init);
  for (const p of this.points[type] || []) {
    if (p[2] < minW) continue;
    const cx = (p[1] - this.west) / R - .5, cy = (this.north - p[0]) / R - .5, r0 = p[3] || 0, rx = Math.ceil((maxKm + r0) / KX), ry = Math.ceil((maxKm + r0) / KY);
    for (let y = Math.max(0, Math.round(cy) - ry); y <= Math.min(H - 1, Math.round(cy) + ry); y++)
      for (let x = Math.max(0, Math.round(cx) - rx); x <= Math.min(W - 1, Math.round(cx) + rx); x++) {
        const d = Math.max(0, Math.hypot((x - cx) * KX, (y - cy) * KY) - r0); if (d > maxKm) continue;
        const i = y * W + x, v = f(d, p[2]); if (init === Infinity ? v < out[i] : v > out[i]) out[i] = v;
      }
  }
  return out;
};
window.PSAREMA_ATTRACTORS.distKm = function (type, maxKm = 10, minW = 0) { return this._grid(type, maxKm, d => d, Infinity, minW); };
window.PSAREMA_ATTRACTORS.kernel = function (type, lambdaKm, maxKm = 4 * lambdaKm) { return this._grid(type, maxKm, (d, w) => w * Math.exp(-d / lambdaKm), 0, 0); };
